-- [R126] Chest Chase update. Paste the WHOLE script into the Command Bar in Edit mode (Play stopped).
-- It checks every script is the exact version it was built for, saves a backup in ServerStorage, then installs.
-- Undo any time: require(game.ServerStorage.ChestChase_R126_Backup.Installer)("undo")   Redo: ...("install")
assert(not game:GetService('RunService'):IsRunning(),'[R126] Stop Play first.')
local storage=game:GetService('ServerStorage')
-- ASCII-only transport keeps embedded sources independent of pasted Unicode and indentation.
local alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
local values={};for i=1,#alphabet do values[alphabet:sub(i,i)]=i-1 end
local function decode(text)
    local out={}
    for i=1,#text,4 do
        local a,b,c,d=text:sub(i,i),text:sub(i+1,i+1),text:sub(i+2,i+2),text:sub(i+3,i+3)
        local n=assert(values[a])*262144+assert(values[b])*4096+(values[c] or 0)*64+(values[d] or 0)
        out[#out+1]=string.char(math.floor(n/65536)%256)
        if c~='=' then out[#out+1]=string.char(math.floor(n/256)%256) end
        if d~='=' then out[#out+1]=string.char(n%256) end
    end
    return table.concat(out)
end
local function sha256(text)
    local band,bxor,bnot,rshift,ror=bit32.band,bit32.bxor,bit32.bnot,bit32.rshift,bit32.rrotate
    local k={0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
    0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
    0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
    0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
    0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2}
    local h={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19}
    local bits=#text*8
    text=text..string.char(128)..string.rep(string.char(0),(55-#text)%64)
    local length={};for i=7,0,-1 do length[#length+1]=string.char(math.floor(bits/2^(8*i))%256) end
    text=text..table.concat(length)
    for offset=1,#text,64 do
        local w={}
        for i=0,15 do local a,b,c,d=text:byte(offset+i*4,offset+i*4+3);w[i]=a*16777216+b*65536+c*256+d end
        for i=16,63 do
            local a,b=w[i-15],w[i-2]
            w[i]=(w[i-16]+bxor(ror(a,7),ror(a,18),rshift(a,3))+w[i-7]+bxor(ror(b,17),ror(b,19),rshift(b,10)))%4294967296
        end
        local a,b,c,d,e,f,g,j=table.unpack(h)
        for i=0,63 do
            local t1=(j+bxor(ror(e,6),ror(e,11),ror(e,25))+bxor(band(e,f),band(bnot(e),g))+k[i+1]+w[i])%4294967296
            local t2=(bxor(ror(a,2),ror(a,13),ror(a,22))+bxor(band(a,b),band(a,c),band(b,c)))%4294967296
            j=g;g=f;f=e;e=(d+t1)%4294967296;d=c;c=b;b=a;a=(t1+t2)%4294967296
        end
        for i,v in ipairs({a,b,c,d,e,f,g,j})do h[i]=(h[i]+v)%4294967296 end
    end
    local out={};for _,v in ipairs(h)do out[#out+1]=string.format('%08x',v)end;return table.concat(out)
end

local existing=storage:FindFirstChild('ChestChase_R126_Backup')
if existing then
 -- Same build pasted again: redo. A different build with the same backup name must never run the old one.
 -- Same build = Build attribute, or an Installer identical to this one (pastes before the attribute never set it).
 local installer=existing:FindFirstChild('Installer')
 local same=existing:GetAttribute('Build')=='ec9b7b2ab9ef909efaed5db65c3ced4823408088208c419bdfae6e26badbc451'or(installer~=nil and installer:IsA('ModuleScript')and sha256(installer.Source)=='ec9b7b2ab9ef909efaed5db65c3ced4823408088208c419bdfae6e26badbc451')
 assert(same,'[R126] An older [R126] backup is in ServerStorage. Undo it first: require(game.ServerStorage.ChestChase_R126_Backup.Installer)("undo") then delete ServerStorage.ChestChase_R126_Backup and paste this again. Nothing changed.')
 existing:SetAttribute('Build','ec9b7b2ab9ef909efaed5db65c3ced4823408088208c419bdfae6e26badbc451')
 require(existing:WaitForChild('Installer'))('install');return
end
local specs={{Path="ReplicatedStorage/SeedPackRules",Class="ModuleScript",BeforeBytes=40488,AfterBytes=40564,BeforeSHA256="04606aee0b3ee0254bf87d8df1b2a0e9014c39f14f3cb89dc88f4544073529eb",AfterSHA256="914511a0cda45d4d498c6a2cd8649410d5381165fcadc647f4534d553049475c"},{Path="ReplicatedStorage/TreadmillBonusRules",Class="ModuleScript",BeforeBytes=9311,AfterBytes=9342,BeforeSHA256="b4ecf32dbdc94510cb30189df52b35361bd65e6deec052f114d3156cccd0ffcf",AfterSHA256="0270f40e5b25b4bfb33aac66f3af313e8f5874bf9156bf49983aaeed00cf0ebd"},{Path="ServerScriptService/ChestChaseServer/Config",Class="ModuleScript",BeforeBytes=188185,AfterBytes=188185,BeforeSHA256="e9fd93dcd0ccbabcfc3216b3e829801231f32e9d5663efa7bbb89a7e351ca3f2",AfterSHA256="ab08d1003ec2352daaafdbd062236440a711830215fb87234a31b386058bd269"},{Path="ServerScriptService/ChestChaseServer/PremiumProgress",Class="ModuleScript",BeforeBytes=17318,AfterBytes=17489,BeforeSHA256="dac3303cad06ed2258fb92ab479d445edd2d1d5207aad476a83324d6afb8a950",AfterSHA256="d0efb8cd4b957cb10a83388016746d8fb34b26dcc2c75ae1668981f0c8e7b8a4"},{Path="ServerScriptService/ChestChaseServer/TreadmillBonusService",Class="ModuleScript",BeforeBytes=7648,AfterBytes=7780,BeforeSHA256="5df7e01b52de8f1e2b081d1fc6894640d1bd8f871e93d007a2894b15dd8fd0a4",AfterSHA256="a45fa14c699d51600e755f3e2d817e293bb35f13139faec10e4f987b089d89e8"}}
local patches={{Path="ReplicatedStorage/SeedPackRules",Patches={{6132,38,table.concat({"LS0gUjEyNjogTWVjaCBwYWNrcyBub3cgcm9sbCBhIHNpemUgdG9vOyB0aGVpciBzZWVkcyBmb2xsb3cgaXQgbGlrZSBhbnkgcGFjayAoYSAxeCBNZWNoIHBhY2sgc3RpbGwgZ2l2ZXMgc2NhbGUgMSku"})}}},{Path="ReplicatedStorage/TreadmillBonusRules",Patches={{722,11,table.concat({"UjEyNjogYSByb2xsZWQgcGFjayBzaXplIGxpa2Ugd29ybGQgcGFja3M7"})}}},{Path="ServerScriptService/ChestChaseServer/Config",Patches={{187122,1,table.concat({"Ng=="})}}},{Path="ServerScriptService/ChestChaseServer/PremiumProgress",Patches={{343,0,table.concat({"LS0gUjEyNiAob3duZXIpOiBib3VnaHQgTWVjaCBwYWNrcyByb2xsIGEgcGFjayBzaXplIGxpa2Ugd29ybGQgcGFja3MgKEJhbGFuY2VSdWxlcy5QYWNrU2l6ZXMpLgpsb2NhbCBTaXplUmFuZG9tPVJhbmRvbS5uZXcoKQo="})},{7160,1,table.concat({"UGFja1J1bGVzLlJvbGxQYWNrU2l6ZShTaXplUmFuZG9tOk5leHROdW1iZXIoKSk="})}}},{Path="ServerScriptService/ChestChaseServer/TreadmillBonusService",Patches={{6753,0,table.concat({"c2l6ZT1QYWNrUnVsZXMuUm9sbFBhY2tTaXplKHNlbGYuUmFuZG9tOk5leHROdW1iZXIoKSkgLS0gUjEyNjogcm9sbHMgYSBwYWNrIHNpemUgbGlrZSB3b3JsZCBwYWNrcwogbG9jYWwg"})},{6844,1,table.concat({"c2l6ZQ=="})},{7568,9,table.concat({"c2l6ZSwnTm9uZScpLFNpemU9cmVjb3JkLlBhY2tTaXpl"})}}}}
local engineSource=decode(table.concat({"","","",""}))
assert(sha256(engineSource)=='ec9b7b2ab9ef909efaed5db65c3ced4823408088208c419bdfae6e26badbc451','[R126] The pasted text was damaged while copying. Nothing changed.')
local editor=game:GetService('ScriptEditorService')
local function unique(parent,name)
 local found,count=nil,0
 for _,child in ipairs(parent:GetChildren())do if child.Name==name then found=child;count+=1 end end
 assert(count==1,'[R126] Missing or duplicated object: '..name..' in '..parent:GetFullName()..'. Nothing changed.');return found
end
local function resolve(path)local item=game;for name in path:gmatch('[^/]+')do item=unique(item,name)end;return item end
local byPath={};for _,p in ipairs(patches)do byPath[p.Path]=p.Patches end
local backup=Instance.new('Folder');backup.Name='ChestChase_R126_Backup'
local sources=Instance.new('Folder');sources.Name='Sources';sources.Parent=backup
for i,spec in ipairs(specs)do
 if spec.New then
  -- A script this update adds. It is created parked inside the backup; the installer moves it into place.
  local parentPath,name=spec.Path:match('^(.*)/([^/]+)$');local home=resolve(parentPath)
  assert(home:FindFirstChild(name)==nil,'[R126] '..spec.Path..' already exists. Nothing changed.')
  local after=''
  for _,p in ipairs(byPath[spec.Path])do after=after..decode(p[3])end
  assert(#after==spec.AfterBytes and sha256(after)==spec.AfterSHA256,'[R126] Patch check failed for '..spec.Path..'. Nothing changed.')
  local entry=Instance.new('Folder');entry.Name=string.format('%02d',i);entry:SetAttribute('Path',spec.Path);entry:SetAttribute('New',true);entry.Parent=sources
  local b=Instance.new('StringValue');b.Name='After';b.Value=after;b.Parent=entry
  local item=Instance.new(spec.Class);item.Name=name;item.Source=after;item.Parent=entry
  local t=Instance.new('ObjectValue');t.Name='Target';t.Value=item;t.Parent=entry
  continue
 end
 local item=resolve(spec.Path)
 assert(item.ClassName==spec.Class,'[R126] '..spec.Path..' is a '..item.ClassName..', expected '..spec.Class..'. Nothing changed.')
 local before=editor:GetEditorSource(item)
 assert(item.Source==before,'[R126] Close or save unsaved edits in '..spec.Path..' first. Nothing changed.')
 assert(#before==spec.BeforeBytes and sha256(before)==spec.BeforeSHA256,'[R126] '..spec.Path..' is not the version this update was built for. Nothing changed.')
 local after=before;local list=byPath[spec.Path]
 table.sort(list,function(a,b)return a[1]>b[1]end)
 for _,p in ipairs(list)do after=after:sub(1,p[1]-1)..decode(p[3])..after:sub(p[1]+p[2])end
 assert(#after==spec.AfterBytes and sha256(after)==spec.AfterSHA256,'[R126] Patch check failed for '..spec.Path..'. Nothing changed.')
 local entry=Instance.new('Folder');entry.Name=string.format('%02d',i);entry:SetAttribute('Path',spec.Path);entry.Parent=sources
 local a=Instance.new('StringValue');a.Name='Before';a.Value=before;a.Parent=entry
 local b=Instance.new('StringValue');b.Name='After';b.Value=after;b.Parent=entry
 local t=Instance.new('ObjectValue');t.Name='Target';t.Value=item;t.Parent=entry
end
local installer=Instance.new('ModuleScript');installer.Name='Installer';installer.Source=engineSource;installer.Parent=backup
backup:SetAttribute('SourceCount',#specs);backup:SetAttribute('Build','ec9b7b2ab9ef909efaed5db65c3ced4823408088208c419bdfae6e26badbc451');backup:SetAttribute('State','Built');backup.Parent=storage
require(installer)('install')
print('[R126] Backup: ServerStorage.ChestChase_R126_Backup   Undo: require(game.ServerStorage.ChestChase_R126_Backup.Installer)("undo")')
